            "formal": "a_i ∈ {2^x - 1 | 1 ≤ x ≤ 60, x ∈ ℤ}",
            "source_sections": [
              "description"
            ]
          },
          {
            "name": "xor_equals_c",
            "description": "The bitwise XOR of all elements in the array must equal the given integer C.",
            "formal": "⊕_{i=1}^{n} a_i = C",
