      "primary_operator": "canonical_witness",
      "target_shift": "从给答案改成给规范解",
      "new_obligation": "输出一个可以直接检查的规范方案"
    },
    "helpers": [
      {
        "id": "canonical_order_pressure",
        "summary": "把规范顺序推进到主状态演化。",
        "must_realize_in": [
          "core_constraints",
          "objective",
          "invariant"
        ],
        "target_axes": [
          "C",
          "O",
          "V"
        ],
        "innovation_role": "让输出对象与验证责任离开原题路径。",
        "difficulty_role": "让状态转移承担新的规范性证明。",
        "prompt_guidance": [
          "让规范顺序进入合法性或最优性定义。",
          "让验证责任依赖全局结构。"
        ],
        "redlines": [
          "不能退化为输出后处理。",
          "不能只加字典序描述。"
        ]
      },
      {
        "id": "proof_bearing_output",
        "summary": "把输出对象升级成带证明责任的规范解。",
        "must_realize_in": [
          "objective",
          "invariant"
        ],
        "target_axes": [
          "O",
          "V"
        ],
        "innovation_role": "让新题输出责任变成可校验的解对象。",
        "difficulty_role": "要求解法解释为什么规范解满足全局约束。",
