{
  "constraints": [
    {
      "name": "tree_topology",
      "description": "The system of rooms and corridors forms an undirected tree with n nodes and n-1 edges, connected without cycles.",
      "formal": "Graph G = (V, E) is a tree, |V|=n, |E|=n-1, connected, acyclic.",
      "source_sections": ["description"]
    },
    {
      "name": "vlad_start",
      "description": "Vlad starts the game in room 1.",
      "formal": "start_V = 1",
      "source_sections": ["description"]
    },
    {
      "name": "vlad_win_condition",
      "description": "Vlad wins if he reaches a room other than 1 that has exactly one incident corridor (a leaf node distinct from the start).",
      "formal": "win_V ≡ ∃ leaf l ≠ 1 such that Vlad arrives at l before any friend meets him",
      "source_sections": ["description"]
    },
    {
      "name": "friends_initial_positions",
      "description": "There are k friends, initially placed at distinct rooms x_i (2 ≤ x_i ≤ n); no two friends share the same room.",
      "formal": "∀ i≠j, x_i ≠ x_j, and x_i ∈ {2,...,n}",
      "source_sections": ["description", "input"]
    },
    {
      "name": "simultaneous_unit_moves",
      "description": "All participants move simultaneously; each can traverse at most one corridor per unit of time.",
      "formal": "∀ time step, each participant moves to an adjacent node or stays; moves happen in parallel.",
      "source_sections": ["description"]
    },
    {
      "name": "optional_stay",
      "description": "Participants may choose not to move during a time unit.",
      "formal": "action ∈ {move to neighbor, stay}",
      "source_sections": ["description"]
    },
    {
      "name": "unlimited_room_capacity",
      "description": "Each room can hold any number of participants simultaneously.",
      "formal": "∀ room, capacity = ∞",
      "source_sections": ["description"]
    },
    {
      "name": "friend_capture_condition",
      "description": "Friends win if at least one of them meets Vlad on a node or edge before Vlad reaches his winning leaf.",
      "formal": "win_F ≡ ∃ time t, ∃ friend f, location(f, t) = location(V, t) (node or edge) and win_V has not occurred by t",
      "source_sections": ["description"]
    },
    {
      "name": "minimal_friend_subset",
      "description": "Determine the minimum size of a subset of friends such that they can always catch Vlad regardless of Vlad's moves; if no such subset exists, output -1.",
      "formal": "ans = min{ |S| : S ⊆ friends, S can guarantee capturing Vlad before he wins } or -1 if no S exists",
      "source_sections": ["description", "output"]
    }
  ]
}

