            {
              "role": "target_interception_size",
              "description": "desired minimum subset size M after rearrangement",
              "type": "integer",
              "value_range": {
                "min": 0,
                "max": "n"
              }
            },
            {
              "role": "initial_item_positions",
              "description": "binary array of length n indicating which compartments initially contain an item (1 means item present)",
              "type": "array",
              "length": {
                "min": "n",
                "max": "n"
              },
              "value_range": {
                "min": 0,
                "max": 1
