    "enabled": true,
    "summary": "把单目标最优题扩展为预算、收益、风险等多指标权衡或前沿查询题。",
    "eligibility": {
      "required_seed_properties": [
        "原题目标附近存在自然的第二评价指标",
        "两个指标之间存在真实冲突，不能同时独立最优"
      ],
      "forbidden_seed_properties": [
        "第二指标只是原目标的同义改写",
        "权衡关系可以由原答案直接后处理得到"
      ]
    },
    "required_axis_changes": {
      "must_change": [
        "C",
        "O",
        "V"
      ]
    },
    "core_transformation": {
      "primary_operator": "single_objective_to_tradeoff_frontier",
      "target_shift": "从单目标最优改成双指标权衡",
      "new_obligation": "定义主指标、约束指标和前沿或最优折中口径"
    },
    "helpers": [
      {
        "id": "secondary_metric_materialization",
        "summary": "引入与原目标冲突的第二指标。",
        "must_realize_in": [
          "core_constraints",
          "objective"
        ],
        "target_axes": [
          "C",
          "O"
        ],
        "innovation_role": "让目标空间从一维扩展到真实权衡。",
        "difficulty_role": "要求算法同时跟踪两个评价维度。",
        "prompt_guidance": [
          "第二指标必须来自原题对象的自然属性。",
          "目标要写清主指标与约束指标的关系。"
        ],
        "redlines": [
          "不能把第二指标写成原指标的别名。",
          "不能只增加一个无影响的附加输出。"
        ]
      },
      {
        "id": "frontier_dominance_rule",
        "summary": "定义支配关系、预算约束或前沿输出口径。",
        "must_realize_in": [
          "objective",
          "invariant"
        ],
        "target_axes": [
          "O",
          "V"
        ],
        "innovation_role": "把答案从单个最优值变成可比较的前沿语义。",
        "difficulty_role": "要求解法维护不可支配状态或折中证明。",
        "prompt_guidance": [
          "说明什么方案被另一个方案支配。",
          "不变量要支撑前沿剪枝或预算转移。"
        ],
        "redlines": [
          "不能只输出两个独立最优值。",
          "不能缺少比较口径。"
        ]
      },
      {
        "id": "coupled_state_expansion",
        "summary": "让核心状态同时承载两个指标的耦合变化。",
        "must_realize_in": [
          "core_constraints",
          "invariant"
        ],
        "target_axes": [
          "C",
          "V"
        ],
        "innovation_role": "阻止多目标退化成两个独立子题。",
        "difficulty_role": "要求证明状态压缩不会丢掉折中信息。",
        "prompt_guidance": [
          "状态或约束必须体现指标之间的相互影响。",
          "不变量要解释为何不能先优化一个再优化另一个。"
        ],
        "redlines": [
          "不能拆成先求目标 A 再求目标 B。",
          "不能让第二指标只在排序时出现。"
        ]
      }
    ],
    "validation_contract": {
      "hard_checks": [
        "第二指标必须与原目标真实冲突",
        "必须定义支配或预算口径",
        "不能退化成两个独立最优值"
      ]
    },
    "examples": {
      "positive": "在最大收益之外加入总风险预算，要求输出每个预算下的最优收益。",
      "negative": "同时输出最大值和该最大值出现的位置。"
    },
    "failure_templates": {
      "not_applicable": "这道种子题缺少自然冲突的第二指标，不适合扩成权衡前沿题。",
