    "core_constraints": {
      "constraints": [
        {
          "name": "storage_tree_topology",
          "description": "储物系统由格子与通道构成一棵无向树，格子数为n，通道数为n-1。",
          "formal": "G = (V, E) 为树，|V|=n, |E|=n-1，连通无环。"
        },
        {
          "name": "target_item_start",
          "description": "目标物品从1号格子进入系统。",
          "formal": "start_item = 1"
        },
        {
          "name": "item_escape_condition",
          "description": "物品到达除1号以外的任意叶子格子即视为逃脱成功。",
          "formal": "win_item ≡ ∃ leaf l ≠ 1 且物品在整理员拦截前到达l。"
        },
        {
          "name": "organizers_initial_positions",
          "description": "有k名整理员初始位于2..n中互异的格子。",
          "formal": "∀ i≠j, pos_i ≠ pos_j, pos_i ∈ [2,n]"
        },
        {
          "name": "simultaneous_unit_moves",
          "description": "所有参与方同时移动；每单位时间最多沿一条通道移动至邻接格子。",
          "formal": "每个时刻，每个参与方选择相邻节点移动或停留，移动并行。"
        },
        {
          "name": "optional_stay",
          "description": "参与方可以选择不走动。",
          "formal": "action ∈ {move to neighbor, stay}"
        },
        {
          "name": "unlimited_cell_capacity",
          "description": "每个格子可容纳任意数量的参与方。",
          "formal": "capacity = ∞"
        },
        {
          "name": "organizer_capture_condition",
          "description": "若在物品逃脱前有整理员与物品在同一格子或通道上相遇，则拦截成功。",
          "formal": "win_organizer ≡ ∃t, ∃org，位置(org,t)与位置(item,t)相同（节点或边）且物品未在此之前逃脱。"
        },
        {
          "name": "minimal_organizer_subset",
          "description": "要求输出方案使用的整理员人数必须等于保证拦截所需的最少人数m；若无方案输出-1。",
          "formal": "方案人数 = min_{S⊆orgs}确保拦截的|S|，或-1若不可拦截。"
        },
        {
          "name": "canonical_solution_definition",
          "description": "规范方案要求：选中的m名整理员按编号升序分配，每名整理员的移动路径必须是从起始格子到拦截点的最短路径；拦截时间戳（即路径长度）按整理员编号非降序排列，且整体方案在满足前述条件下字典序最小。",
          "formal": "对选中整理员标号o1<o2<...<om，令d_i为oi到其拦截点的距离，要求d_1 ≤ d_2 ≤ ... ≤ d_m；同时oi的路径必须是所有可能拦截方案中按编号顺序的最短路径，且整体路径序列（按编号）字典序最小。"
        },
        {
          "name": "canonical_constraint_priority",
          "description": "规范输出的约束优先于单纯的最小人数查找；解法必须同时满足最小性和规范性，且在状态搜索中规范性作为硬约束参与剪枝。",
          "formal": "在任意可行拦截方案上叠加规范顺序约束，合法解集合缩小，但仍保持最小性可达。"
        }
      ]
    },
    "objective": {
      "type": "produce_canonical_solution",
      "description": "对每个测试用例，输出一个规范整理方案。若无法拦截，输出-1；否则输出第一行为最少数m，接着m行，每行为一名整理员的编号、起始格、然后一连串移动到的相邻格子（中间用空格分隔），直到拦截发生。方案必须满足 canonical_solution_definition 中的规范，且附带正确性证明（隐含在输出格式合规性与后续校验中）。",
      "target": "规范方案元组(m, list of (org_id, path))",
      "requires_canonical_proof": true
    },
    "invariant": {
      "invariants": [
        {
          "name": "canonical_solution_existence_invariant",
          "description": "基于原题算法不变式，当拦截可行时，总存在至少一个规范方案；算法在寻找最小子集的过程中保证能够构造出这样的规范方案。",
          "properties": {
            "existence_guaranteed": true,
            "constructible_from_dp": true
          }
        },
        {
          "name": "canonical_ordering_proof_obligation",
          "description": "输出的路径序列必须可证明满足编号顺序的距离非降以及字典序最小性。",
          "properties": {
            "proof_obligation": "order_and_lexical_minimality"
          }
        },
        {
          "name": "optimality_proof_obligation",
          "description": "所输出的方案人数必须与经典最小拦截子集大小一致，且规范处理未造成人数膨胀。",
          "properties": {
            "proof_obligation": "minimality_preserved"
          }
        }
      ]
    },
    "difficulty": "medium_hard"
  },
  "algorithmic_delta_claim": {
    "seed_solver_core": "树形DP或双BFS：计算每个节点到最近朋友的距离，自底向上贪心选取叶子处需要增补的朋友，得到最小子集大小。",
    "reusable_subroutines": "节点到最近朋友距离计算、叶子必要性判断、自底向上DP框架。",
    "new_solver_core": "在DP过程中同时对每个必要拦截点记录最早可拦截的整理员候选；计算完后按整理员编号排序，对每个选中的整理员追溯其从初始位置到拦截点的最短路径（需保持距离序列非降，通过调整同距离整理员的分配顺序或细微路径选择满足字典序）。最后输出序列。",
    "new_proof_obligation": "证明按编号排序后距离非降的整理员分配总是存在，且当多个整理员距离相同时通过路径细节调整可达到字典序最小；进一步证明该规范方案不改变最少人数。",
    "why_direct_reuse_fails": "原算法仅输出整数，未保留具体拦截分配，且规范顺序要求对整理员进行全局排序与路径字典序比较，单靠原DP回溯无法直接获得规范解。"
  },
  "anti_shallow_rationale": "输出形态从数值彻底变为带严格规范顺序的方案对象，核心约束显式增加了 canonical_solution_definition 和规范优先级，迫使解法在搜索最小集时同步维护顺序证明，不再仅仅是数值计算。收纳背景仅作为术语映射，不改变这一质变。",
  "applied_helpers": [
    {
      "id": "canonical_order_pressure",
      "selection_reason": "规则要求将规范顺序推入主状态演化，避免输出后处理。",
      "affected_axes": ["C", "O", "V"],
      "schema_changes": [
        "core_constraints中添加canonical_solution_definition与canonical_constraint_priority",
        "objective改为produce_canonical_solution且明确规范顺序要求",
        "invariant增加canonical_ordering_proof_obligation"
      ],
      "innovation_reason": "输出对象不再是选择集合，而是附加强排序条件的路径序列；解法必须内化顺序证明。",
      "difficulty_reason": "要求解法在DP过程中预先考虑分配顺序，增加了状态表示与证明复杂度。"
    },
    {
      "id": "proof_bearing_output",
      "selection_reason": "输出对象需升级为带证明责任的规范解。",
      "affected_axes": ["O", "V"],
      "schema_changes": [
        "objective新增强制要求附带正确性证明（通过隐含校验）",
        "invariant新增optimality_proof_obligation"
      ],
      "innovation_reason": "题目不再接受无证明的方案输出；正确性必须可凭输出格式直接核验。",
      "difficulty_reason": "求解器需额外生成路径证据并确保其与规范不矛盾，提高了实现门槛。"
    },
    {
      "id": "constraint_reweighting",
      "selection_reason": "规范产出要求必须进入主约束优先级。",
      "affected_axes": ["C", "V"],
      "schema_changes": [
        "core_constraints中加入canonical_constraint_priority，明确规范约束在搜索中优先",
        "invariant体现新的约束主次关系"
      ],
      "innovation_reason": "搜索空间不再只由拦截可行性定义，规范性条件成为核心剪枝依据。",
      "difficulty_reason": "算法必须同时处理拦截可行性、最小性和规范顺序三层约束，状态转移更复杂。"
    }
  ],
  "shared_core_summary": "",
