messages.content:
请审查该规划是否兑现规则专属合同。
要求：
- `message` 直接概括结论，不要泛泛而谈。
- `errors` 只写真正构成拒绝的规则专属问题；通过时返回空数组。
- `evidence` 必须引用给定 payload、schema 或规则声明中的具体内容。
- 如果规则声明了 `helpers`，要逐条核对 helper 是否全部出现，以及每个 helper 是否兑现了自己的目标变化轴、落点和 redlines。
- 如果不能确认已经兑现规则专属合同，返回 `fail`。

{
  "review_type": "rule_plan_validation",
  "mode": "single_seed_extension",
  "review_role": "你扮演一名规范解规划审查官，重点确认规划是否真正把输出责任升级为可比较、可校验的规范解。",
  "review_brief": "确认规划是否明确了规范解的定义、比较口径与校验方式，并且规范性会改变主要求解责任。",
  "rule_under_review": {
    "id": "canonical_witness",
    "family": "output_upgrade",
    "summary": "把原题改成需要输出并校验一个规范解的新题。",
    "audit_tags": [
      "single_seed",
      "witness",
      "output_contract"
    ],
    "required_axis_changes": {
      "must_change": [
        "C",
        "O",
        "V"
      ]
    },
    "core_transformation": {
      "primary_operator": "canonical_witness",
      "target_shift": "从给答案改成给规范解",
      "new_obligation": "输出一个可以直接检查的规范方案"
    },
    "helpers": [
      {
        "id": "canonical_order_pressure",
        "summary": "把规范顺序推进到主状态演化。",
        "must_realize_in": [
          "core_constraints",
          "objective",
          "invariant"
        ],
        "target_axes": [
          "C",
          "O",
          "V"
        ],
        "innovation_role": "让输出对象与验证责任离开原题路径。",
        "difficulty_role": "让状态转移承担新的规范性证明。",
        "prompt_guidance": [
          "让规范顺序进入合法性或最优性定义。",
          "让验证责任依赖全局结构。"
        ],
        "redlines": [
          "不能退化为输出后处理。",
          "不能只加字典序描述。"
        ]
      },
      {
        "id": "proof_bearing_output",
        "summary": "把输出对象升级成带证明责任的规范解。",
        "must_realize_in": [
          "objective",
          "invariant"
        ],
        "target_axes": [
          "O",
          "V"
        ],
        "innovation_role": "让新题输出责任变成可校验的解对象。",
        "difficulty_role": "要求解法解释为什么规范解满足全局约束。",
        "prompt_guidance": [
          "让输出对象直接承接新校验责任。",
          "不要把证明责任留在题面备注之外。"
        ],
        "redlines": [
          "不能把规范性留给说明文补充。",
          "不能只要求输出任意方案。"
        ]
      },
      {
        "id": "constraint_reweighting",
        "summary": "重排主约束优先级，让规范解要求进入主约束。",
        "must_realize_in": [
          "core_constraints",
          "invariant"
        ],
        "target_axes": [
          "C",
          "V"
        ],
        "innovation_role": "让规范性要求进入主约束的优先级分配。",
        "difficulty_role": "迫使解法在状态设计里处理新的约束主次关系。",
        "prompt_guidance": [
          "让规范要求改变主约束的优先级组织。",
          "让不变量反映新的约束主次关系。"
        ],
        "redlines": [
          "不能只增加一句格式要求。",
          "不能保持原主约束完全不动。"
        ]
      }
    ],
    "validation_contract": {
      "hard_checks": [
        "输出要求必须真正变了",
        "规范要求要影响主要解法",
        "规定必须变化的轴都要真的变化"
      ]
    },
    "planner_output_contract": {
      "required_fields": [
        "eligibility_reason",
        "core_transformation_summary",
        "difference_plan",
        "new_schema",
        "algorithmic_delta_claim",
        "anti_shallow_rationale",
        "applied_helpers"
      ]
    },
    "examples": {
      "positive": "把是否可行改成输出字典序最小的合法构造。",
      "negative": "原题先求值，再顺手回溯一个任意方案。"
    },
    "failure_templates": {
      "not_applicable": "这道种子题缺少适合做规范化的解对象，不适合扩成规范解题。",
      "difference_insufficient": "加上规范解输出之后，主要解法几乎没变，还是表面修改。"
    }
  },
